     2→use traits::*;
     3→
     4→pub mod batch_addition;
     5→pub mod batch_inversion;
     6→mod booth_encoding;
     7→pub mod fixed_base_msm;
     8→pub mod fixed_base_msm_window;
     9→pub mod lincomb;
    10→
    11→// Re-exporting the blstrs crate
    12→
    13→// Re-export ff and group, so other crates do not need to directly import(and independently version) them
    14→pub use ff;
    15→pub use group;
    16→
    17→pub mod traits {
    18→    pub use ff::{Field, PrimeField};
    19→    pub use group::{prime::PrimeCurveAffine, Curve, Group};
    20→}
    21→
    22→/// Affine representation of a point in the BLS12-381 G1 curve group.
    23→pub type G1Point = blstrs::G1Affine;
    24→
    25→/// Projective representation of a point in the BLS12-381 G1 curve group.
    26→pub type G1Projective = blstrs::G1Projective;
    27→
    28→/// Affine representation of a point in the BLS12-381 G2 curve group.
    29→pub type G2Point = blstrs::G2Affine;
    30→
    31→/// Projective representation of a point in the BLS12-381 G2 curve group.
    32→pub type G2Projective = blstrs::G2Projective;
    33→
    34→/// Precomputed G2 point for efficient pairing computations.
    35→///
    36→/// This representation allows reusing expensive Miller loop setup across multiple pairings.
    37→pub type G2Prepared = blstrs::G2Prepared;
    38→
    39→/// Scalar field element for the BLS12-381 curve.
    40→///
    41→/// Used as exponents in scalar multiplication and other finite field operations.
    42→pub type Scalar = blstrs::Scalar;
    43→
    44→/// Checks whether the product of pairings over the given G1 × G2 pairs equals the identity.
    45→pub fn multi_pairings(pairs: &[(&G1Point, &G2Prepared)]) -> bool {
    46→    blstrs::Bls12::multi_miller_loop(pairs)
    47→        .final_exponentiation()
    48→        .is_identity()
    49→        .into()
    50→}
    51→
    52→/// Converts Projective points to normalized points efficiently.
    53→///
    54→// Note: This efficient variation is needed here and not for G2 because it is called
    55→// multiple times for MSM pre-computations.
    56→pub fn g1_batch_normalize(projective_points: &[G1Projective]) -> Vec<G1Point> {
    57→    if projective_points.is_empty() {
    58→        return Vec::new();
    59→    }
    60→
    61→    // Track which points are identity and create a filtered vec without them
    62→    //
    63→    // This is because blst will convert all points into the identity point
    64→    // if even one of them is the identity point.
    65→    let mut identity_positions = Vec::new();
    66→    let mut non_identity_points = Vec::new();
    67→
    68→    for (idx, point) in projective_points.iter().enumerate() {
    69→        if point.is_identity().into() {
    70→            identity_positions.push(idx);
    71→        } else {
    72→            non_identity_points.push(*point);
    73→        }
    74→    }
    75→
    76→    // If all points are identity, return a vector of identity points
    77→    if non_identity_points.is_empty() {
    78→        return vec![G1Point::identity(); projective_points.len()];
    79→    }
    80→
    81→    // Convert non-identity points to BLST representation and normalize
    82→    let points = unsafe {
    83→        std::slice::from_raw_parts(
    84→            non_identity_points.as_ptr().cast::<blst::blst_p1>(),
    85→            non_identity_points.len(),
    86→        )
    87→    };
    88→
    89→    let normalized = blst::p1_affines::from(points);
    90→
    91→    // Convert normalized points back to G1Points
    92→    let mut result: Vec<_> = normalized
    93→        .as_slice()
    94→        .iter()
    95→        .map(|p| G1Point::from_raw_unchecked(p.x.into(), p.y.into(), false))
    96→        .collect();
    97→
    98→    // Reinsert identity points at their original positions
    99→    for pos in identity_positions {
   100→        result.insert(pos, G1Point::identity());
